import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DaAAbehN.js";const h=JSON.parse('{"title":"Codex from Zero to One","description":"","frontmatter":{"layout":"home","hero":{"name":"Codex from Zero to One","text":"Let AI Handle Programming and Office Work","tagline":"Designed for working professionals and content creators with zero programming background","actions":[{"theme":"brand","text":"→ Start Lesson 1","link":"/en/modules/module-1/lesson-1"},{"theme":"alt","text":"Course Overview","link":"/en/appendix/prep-checklist"}]},"features":[{"title":"Organize Files","details":"Use Codex to organize folders, batch rename, and categorize files"},{"title":"Generate Webpages","details":"Describe what you want in plain language, let Codex build it"},{"title":"Web Research","details":"Have Codex search the web and compile reports"},{"title":"Automation","details":"Automate repetitive tasks and save time"},{"title":"Create PPTs","details":"Use Codex skills to quickly complete complex tasks"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),n={name:"en/index.md"};function s(i,e,l,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="codex-from-zero-to-one" tabindex="-1">Codex from Zero to One <a class="header-anchor" href="#codex-from-zero-to-one" aria-label="Permalink to &quot;Codex from Zero to One&quot;">​</a></h1><h2 id="let-ai-handle-programming-and-office-work" tabindex="-1">Let AI Handle Programming and Office Work <a class="header-anchor" href="#let-ai-handle-programming-and-office-work" aria-label="Permalink to &quot;Let AI Handle Programming and Office Work&quot;">​</a></h2><blockquote><p>Designed for working professionals and content creators with zero programming background Use natural language to make AI your personal assistant</p></blockquote><h2 id="course-overview" tabindex="-1">Course Overview <a class="header-anchor" href="#course-overview" aria-label="Permalink to &quot;Course Overview&quot;">​</a></h2><p>Ever had these experiences?</p><ul><li>Want to write a small tool to organize files, but don&#39;t know how to code</li><li>Need to make a PPT, spending half a day finding materials and formatting</li><li>Want to analyze a pile of data, but Excel formulas and search engines can&#39;t help</li><li>Heard AI can write code and help with office work, but have no idea where to start</li></ul><p>If you relate to any of these, this course is for you.</p><p><strong>Codex is OpenAI&#39;s AI coding agent.</strong> It&#39;s not just a simple &quot;chatbot&quot; — it can read your projects, write code, run commands, call tools, and even help you organize computer folders, generate PPTs, and do data analysis.</p><p>Most importantly: <strong>you don&#39;t need to know how to code</strong>. As long as you can speak naturally, you can use Codex to complete these tasks.</p><p>Inside OpenAI, lawyers use Codex to organize contract clauses, recruiters use Codex to screen resumes, and operations staff use Codex to create data reports. You can too.</p><h2 id="course-structure" tabindex="-1">Course Structure <a class="header-anchor" href="#course-structure" aria-label="Permalink to &quot;Course Structure&quot;">​</a></h2><p>This course has <strong>6 modules</strong>, about <strong>16 lessons + 4 hands-on projects</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Module 1: Understanding Codex       →  Learn what it is and what it can do</span></span>
<span class="line"><span>Module 2: Getting Started            →  Install, log in, have your first conversation</span></span>
<span class="line"><span>Module 3: Core Features              →  File operations, natural language, web search, automation</span></span>
<span class="line"><span>Module 4: Practical Tips             →  Write better prompts, use safely, call skills</span></span>
<span class="line"><span>Module 5: Project Practice           →  4 complete projects, from beginner to advanced</span></span>
<span class="line"><span>Module 6: Summary &amp; Next Steps       →  Review, FAQ, what to learn next</span></span></code></pre></div><h2 id="learning-paths" tabindex="-1">Learning Paths <a class="header-anchor" href="#learning-paths" aria-label="Permalink to &quot;Learning Paths&quot;">​</a></h2><h3 id="complete-learning-recommended" tabindex="-1">Complete Learning (Recommended) <a class="header-anchor" href="#complete-learning-recommended" aria-label="Permalink to &quot;Complete Learning (Recommended)&quot;">​</a></h3><p>Study in module order, total duration about <strong>5-7 hours</strong>:</p><table tabindex="0"><thead><tr><th>Module</th><th>Estimated Time</th><th>Description</th></tr></thead><tbody><tr><td>Module 1</td><td>45 minutes</td><td>Build understanding, no need to operate yet</td></tr><tr><td>Module 2</td><td>60 minutes</td><td>Hands-on installation, login, run first task</td></tr><tr><td>Module 3</td><td>90 minutes</td><td>Core features, practice every lesson</td></tr><tr><td>Module 4</td><td>45 minutes</td><td>Skill improvement, learn and use simultaneously</td></tr><tr><td>Module 5</td><td>120 minutes</td><td>Project practice, recommended to split over two days</td></tr><tr><td>Module 6</td><td>30 minutes</td><td>Review and plan next steps</td></tr></tbody></table><h3 id="crash-course" tabindex="-1">Crash Course <a class="header-anchor" href="#crash-course" aria-label="Permalink to &quot;Crash Course&quot;">​</a></h3><p>If time is tight, you can just learn:</p><ol><li><strong>Module 1</strong> (Understanding Codex) → 15 minutes</li><li><strong>Module 2</strong> (Install + First Conversation) → 30 minutes</li><li><strong>Module 5 · Project 1</strong> (Organize Computer) → 20 minutes</li></ol><p>This way you can use Codex for the most practical things.</p><h2 id="pre-course-preparation" tabindex="-1">Pre-course Preparation <a class="header-anchor" href="#pre-course-preparation" aria-label="Permalink to &quot;Pre-course Preparation&quot;">​</a></h2><p>Before starting, make sure you have the following ready:</p><ol><li><strong>ChatGPT Account</strong> — Free version works, but Plus/Pro has more quota</li><li><strong>A Computer</strong> — macOS or Windows both work</li><li><strong>Stable Internet Connection</strong> — Codex needs to connect to the internet</li><li><strong>A Folder to Organize</strong> — For practice (e.g., &quot;Downloads&quot; folder)</li></ol><blockquote><p>📋 For the detailed preparation checklist, please refer to <a href="/CodexCourse/en/appendix/prep-checklist.html">Pre-course Checklist</a></p></blockquote><h2 id="what-if-i-encounter-problems" tabindex="-1">What If I Encounter Problems? <a class="header-anchor" href="#what-if-i-encounter-problems" aria-label="Permalink to &quot;What If I Encounter Problems?&quot;">​</a></h2><ul><li>Installation issues → See <a href="/CodexCourse/en/appendix/faq.html">FAQ</a></li><li>Don&#39;t understand terms → See <a href="/CodexCourse/en/appendix/glossary.html">Glossary</a></li><li>Self-assessment after course → Fill out <a href="/CodexCourse/en/appendix/feedback.html">Feedback Form</a></li></ul><hr><p><em>Ready? Let&#39;s start Lesson 1 👉 <a href="/CodexCourse/en/modules/module-1/lesson-1.html">Lesson 1: What is an AI Programming Assistant?</a></em></p>`,29)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
